# Import of required libraries
import skyramp
import json
import os
import time


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")

# A recipe write must carry the whole recipe body, so each write below starts from
# the recipe as the API last returned it and replaces only its notes.

def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    # Declaration of variables
    recipe_name = skyramp.unique_suffix("skyramp note codepoints")
    # 255 two-byte code points: 255 characters but 510 UTF-8 bytes
    note_at_limit = "\u00e9" * 255

    # Request Body
    recipes_POST_request_body = r'''{
        "name": "skyramp note codepoints"
    }'''

    # Execute Request
    recipes_POST_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes",
        method="POST",
        body=recipes_POST_request_body,
        headers=headers,
        data_override={"name": recipe_name}
    )

    # Generated Assertions
    assert recipes_POST_response.status_code == 201
    # the create response is the new recipe's slug, as a bare JSON string
    recipes = json.loads(recipes_POST_response.response_body)
    assert isinstance(recipes, str) and recipes != ""
    assert recipes.startswith("skyramp-note-codepoints")

    # Execute Request
    recipes_recipes_GET_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="GET",
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_GET_response.status_code == 200
    assert json.loads(recipes_recipes_GET_response.response_body)["slug"] == recipes
    assert skyramp.get_response_value(recipes_recipes_GET_response, "name") == recipe_name
    assert len(skyramp.get_response_value(recipes_recipes_GET_response, "notes")) == 0
    assert skyramp.get_response_value(recipes_recipes_GET_response, "notes.0") is None

    # Request Body: the recipe as read back, with a note of 255 two-byte code points
    recipe_at_limit = json.loads(recipes_recipes_GET_response.response_body)
    recipe_at_limit["notes"] = [{"title": "unicode at limit", "text": note_at_limit}]
    recipes_recipes_PUT_request_body = json.dumps(recipe_at_limit)

    # Execute Request
    recipes_recipes_PUT_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="PUT",
        body=recipes_recipes_PUT_request_body,
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_PUT_response.status_code == 200
    assert len(skyramp.get_response_value(recipes_recipes_PUT_response, "notes")) == 1
    assert skyramp.get_response_value(recipes_recipes_PUT_response, "notes.0.title") == "unicode at limit"
    assert skyramp.get_response_value(recipes_recipes_PUT_response, "notes.0.text") == note_at_limit
    assert skyramp.get_response_value(recipes_recipes_PUT_response, "notes.1") is None

    # Execute Request
    recipes_recipes_GET_1_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="GET",
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_GET_1_response.status_code == 200
    stored_note_text = skyramp.get_response_value(recipes_recipes_GET_1_response, "notes.0.text")
    assert stored_note_text == note_at_limit
    assert len(stored_note_text) == 255
    # 510 bytes: a byte-based limit would have rejected or truncated this value
    assert len(stored_note_text.encode("utf-8")) == 510
    assert skyramp.get_response_value(recipes_recipes_GET_1_response, "notes.0.title") == "unicode at limit"
    assert skyramp.get_response_value(recipes_recipes_GET_1_response, "notes.1") is None

    # Request Body: the stored recipe with a note of 256 code points
    recipe_over_limit = json.loads(recipes_recipes_PUT_response.response_body)
    recipe_over_limit["notes"] = [{"title": "unicode over limit", "text": note_at_limit + "\u00e9"}]
    recipes_recipes_PUT_1_request_body = json.dumps(recipe_over_limit)

    # Execute Request
    recipes_recipes_PUT_1_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="PUT",
        body=recipes_recipes_PUT_1_request_body,
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_PUT_1_response.status_code == 422
    assert skyramp.get_response_value(recipes_recipes_PUT_1_response, "detail.0.type") == "string_too_long"
    assert skyramp.get_response_value(recipes_recipes_PUT_1_response, "detail.0.msg") == "String should have at most 255 characters"
    assert skyramp.get_response_value(recipes_recipes_PUT_1_response, "detail.0.loc") == ["body", "notes", 0, "text"]
    assert skyramp.get_response_value(recipes_recipes_PUT_1_response, "detail.1") is None

    # Execute Request
    recipes_recipes_GET_2_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="GET",
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_GET_2_response.status_code == 200
    # the rejected 256-code-point request persisted nothing
    assert len(skyramp.get_response_value(recipes_recipes_GET_2_response, "notes")) == 1
    assert skyramp.get_response_value(recipes_recipes_GET_2_response, "notes.0.title") == "unicode at limit"
    assert skyramp.get_response_value(recipes_recipes_GET_2_response, "notes.0.text") == note_at_limit
    assert skyramp.get_response_value(recipes_recipes_GET_2_response, "notes.1") is None

    # Execute Request
    recipes_recipes_DELETE_response = client.send_request(
        url=URL_localhost,
        path="/api/recipes/{recipes}",
        method="DELETE",
        headers=headers,
        path_params={"recipes": recipes}
    )

    # Generated Assertions
    assert recipes_recipes_DELETE_response.status_code == 200


